"""Unchanged CT9 target: read-only reference/load readiness, never admission.

Native rows and field inventories are evaluated on the actual flat target.
No target timestep/history or physical trajectory is generated by this tool.
"""
import argparse,os,resource,shutil,xml.etree.ElementTree as ET
from pathlib import Path
from functools import lru_cache
from rans_qualification import THREADS,exact_vector_hash
os.environ.update(THREADS)
import numpy as np
from scipy.sparse import csr_matrix
import ct_accepted8_native as n
from ct_accepted9_pressure_run import sealed
from ct_accepted9_gate import pair
from ct_accepted_pilot import replay
from ct_accepted_open import probe,require
from ct_accepted3_metrics import inventory
from ct_accepted10_compare import gradients
from ct_accepted_feasibility import write_json
from rans_request_manifest import RequestManifest,sha,runtime_identity
from run_cls_epawf_picard import set_parameter,write


def main():
    p=argparse.ArgumentParser(description=__doc__)
    for k in ('ct9','runtime','candidate','output'):p.add_argument('--'+k,type=Path,required=True)
    a=p.parse_args();resource.setrlimit(resource.RLIMIT_CORE,(0,0));resource.setrlimit(resource.RLIMIT_AS,(16*1024**3,16*1024**3));os.environ['LD_LIBRARY_PATH']=str(a.runtime/'lib');n.reference=lru_cache(None)(n.reference)
    capacity=sealed(a.ct9/'capacity-v2');row=capacity['cases']['target-p4'];c=row['case'];folder=a.ct9/'capacity-v2/target-p4';native=n.read(folder/'case.evolution.json');initial=n.read(folder/'frozen.json');candidate=sealed(a.candidate)
    require(sha(folder/'case.evolution.json')==row['native_report_sha256'] and sha(folder/'frozen.json')==row['frozen_packet_sha256'],'changed sealed target state/packet')
    require(len(native['state'])==60907 and native['time']==0. and initial['observation']['state']==native['state'],'foreign target state')
    target_contract=Path(__file__).resolve().parents[4]/'docs/plans/cao-tamura-accepted-10-evidence/target-preflight-v1.json'
    m=RequestManifest(a.output,dict(schema='CT10TargetReadinessV1',case=c,contract=sha(target_contract),capacity=sha(a.ct9/'capacity-v2/results.json'),candidate=sha(a.candidate/'results.json'),runtime=runtime_identity(a.runtime/'RANSPreservationProbe'),source=sha(Path(__file__)),state=exact_vector_hash(native['state']),configuration=sha(folder/'case.xml'),scope='original unchanged actual target, static only; no replacement of required strip pressure, timestep or evolved resource gates'))
    dest=a.output/'target';dest.mkdir();shutil.copy2(folder/'case.xml',dest/'case.xml');grid,sides,weights,count=n.inventory(c)
    req=replay(initial,native['state'],0.,grid,grid_sides=sides,export_faces_only=True,export_test_basis=True,export_neutral_composite_reference=True,export_ct10_momentum=True,ct10_export_points=False,export_sparse_backend=True,sparse_alpha=1000.)
    packet,e=probe(a.runtime,dest,req,'readiness');require(e['exit_code']==0,'target read-only preflight failed:'+str(packet.get('failure')));n.binding(packet,c);require(packet['observation']['state']==native['state'],'target replay changed native state')
    metrics=n.physical_metrics(packet,native['state'],c,weights,count);dom=inventory(packet['test_basis'],packet['observation']['grid'],np.asarray(native['state']),packet['observation']['offsets'],'A95',packet['observation']['grid_sides']);mom=packet['ct10_momentum'];free=np.asarray(mom['free_rows'],int);actual=np.asarray(mom['total_actual']);analytic=np.asarray(mom['total_analytic']);delta=actual-analytic
    terms={}
    for key,v in mom['actual'].items():
        dr=np.asarray(v)-np.asarray(mom['analytic'][key]);terms[key]=dict(free_maximum=float(max(abs(dr[free]))),free_signed_sum=float(np.sum(dr[free])),prescribed_maximum=float(max(abs(dr[np.asarray(mom['fixed_rows'],int)]))))
    off=packet['observation']['offsets'];npres=off[6]-off[4];rr=[];cc=[];vv=[]
    require(packet['sparse_backend']['pressure_rows']==npres and packet['sparse_backend']['pressure_C_nnz']==0,'target pressure rows/C differ from admitted absolute-pressure convention')
    for i,(q,r) in enumerate(zip(packet['test_basis'][:count],packet['observation']['grid_regions'][:count],strict=True)):
        for j,v in zip(q['pressure']['ids'],q['pressure']['phi'],strict=True):rr.append(i);cc.append(off[4+r]+j-off[4]);vv.append(v)
    B=csr_matrix((vv,(rr,cc)),shape=(count,npres));p0=np.asarray(packet['sparse_backend']['pressure_increment']);quad=[]
    for orders in ((48,12,12,16,64),(64,16,12,20,64)):
        sub=a.output/('q'+str(orders[0]));sub.mkdir();root=ET.parse(folder/'case.xml').getroot()
        for key,val in zip(('RANSWallNormalOrder','RANSWallTangentialOrder','RANSWallMassOrder','RANSWallVolumeOrder','RANSWallInterfaceOrder'),orders,strict=True):set_parameter(root,key,val)
        write(root,sub/'case.xml');rq=replay(initial,native['state'],0.,[],export_ct10_momentum=True,ct10_export_points=False,export_sparse_backend=True,sparse_alpha=1000.)
        qp,qe=probe(a.runtime,sub,rq,'quadrature');require(qe['exit_code']==0,'target frozen-quadrature operation failed:'+str(qp.get('failure')));require(qp['observation']['state']==native['state'],'target governing-quadrature control changed coefficients')
        pd=B@(np.asarray(qp['sparse_backend']['pressure_increment'])-p0);w=np.asarray(weights);scaled=float(np.sqrt(w@(pd*pd)/w.sum()))/c['ustar']**2;maximum=float(max(abs(pd)))/c['ustar']**2
        require(maximum<1e-8,'target governing-quadrature pressure uncertainty exceeds declared bound')
        quad.append(dict(orders=orders,execution=qe,packet_sha256=sha(sub/'quadrature.json'),frozen_pressure_scaled_RMS_change=scaled,maximum_scaled_pressure_change=maximum,signed_load_reconstruction=qp['ct10_momentum']['maximum_reconstruction_error'],sparse_true_residuals={k:qp['sparse_backend'][k] for k in ('predictor_residual','predictor_rhs_maximum','true_pressure_residual','pressure_rhs_maximum','true_continuity','predictor_factor_nnz')}))
    out=dict(schema='CT10TargetReadinessV1',static_execution='pass',strip_qualification=pair(candidate),target_evolution='not_admitted_pending_all_independent_gates',native_count=60907,mesh=c,configuration_sha256=sha(folder/'case.xml'),actual_initial_sha256=exact_vector_hash(native['state']),native_report_sha256=sha(folder/'case.evolution.json'),packet_sha256=sha(dest/'readiness.json'),execution=e,initial_metrics=metrics,initial_gradients=gradients(packet,native['state'],c,weights,count),physical_domain=dom,native_audit=packet['observation']['audit_alpha_zero'],reference_agreement=n.oracle_agreement(packet,c),signed_momentum=dict(reconstruction=mom['maximum_reconstruction_error'],free_actual_maximum=float(max(abs(actual[free]))),free_analytic_maximum=float(max(abs(analytic[free]))),free_representation_difference_maximum=float(max(abs(delta[free]))),component_differences=terms),quadrature=packet['observation']['actual_quadrature'],capacity_reuse=dict(unchanged_mesh_and_state=True,receipt=str(a.ct9/'capacity-v2/results.json'),sha256=sha(a.ct9/'capacity-v2/results.json'),flow_nnz=row['sparse_backend']['flow_nnz'],predictor_factor_nnz=row['sparse_backend']['predictor_factor_nnz'],scope='sealed initial/frozen capacity only, no evolved factor-fill or accepted-step measurement'),missing_gates=['passing complete strip uncertainty contract','target governing-quadrature pressure sensitivity and evolving cutoff control','justified target timestep pair','paired accepted-step cost and evolved fill','finite first .01-transit campaign contract'],terrain='affine flat inventory only; mapped numbering, Cartesian/cofactor transmission and curved temporal/spatial qualification remain outstanding')
    strip=pair(candidate);abs_errors=metrics['absolute_reference_error'];static_ok=metrics['status']=='pass' and dom['domain_failure_count']==0 and dom['minima']['covariance']['value']>=-1e-10*c['K0'] and out['reference_agreement']['status']=='pass' and all(v['scaled']<=(1e-4 if k=='w' else 1e-3) for k,v in abs_errors.items()) and mom['maximum_reconstruction_error']<=2e-10
    out['static_admission']=dict(status='pass' if static_ok else 'fail',scope='initial reference/projection/domain/load/quadrature, not evolved preservation');out['frozen_quadrature']=quad
    out['native_frozen_flow']={k:v for k,v in packet['sparse_backend'].items() if k not in ('predictor','pressure_increment','consistent_mass_correction','scalars')};out['native_frozen_flow']['scalars']=[{k:v for k,v in q.items() if k!='diagnostic_increment'} for q in packet['sparse_backend']['scalars']]
    out['mesh_scale_preflight']=dict(minimum_dx=min(b-a for a,b in zip(c['x'][:-1],c['x'][1:],strict=True)),minimum_dz=min(b-a for a,b in zip(c['knots'][:-1],c['knots'][1:],strict=True)),reference_roof_speed=float(n.reference(n.col(c),c['Z'],True)[0]),timesteps=[.001,.0005],role='actual mesh/reference scales; independent paired accuracy still required')
    write_json(a.output/'results.json',out);m.seal(a.output,['results.json']);print('CT10 actual target static assessment',out['static_admission'],'strip',strip,flush=True);return 0 if static_ok else 1
if __name__=='__main__':raise SystemExit(main())
